import { Program } from "@coral-xyz/anchor";
import BN from "bn.js";
import { PumpAmm } from "../types/pump_amm";
import { Connection, PublicKey, TransactionInstruction } from "@solana/web3.js";
import { NATIVE_MINT, TOKEN_2022_PROGRAM_ID } from "@solana/spl-token";
import { canonicalPumpPoolPda, GLOBAL_CONFIG_PDA, PUMP_MINT } from "./pda";
import { getPumpAmmProgram } from "./util";
import { PUMP_AMM_SDK } from "./offlinePumpAmm";
import { GlobalConfig } from "../types/sdk";

export class PumpAmmAdminSdk {
  private readonly connection: Connection;
  private readonly program: Program<PumpAmm>;

  constructor(connection: Connection) {
    this.connection = connection;
    this.program = getPumpAmmProgram(connection);
  }

  /**
   * Decoded through `PumpAmmSdk.decodeGlobalConfig`, which zero-pads shorter (pre-upgrade)
   * accounts: Anchor's own `fetch` throws on the live 940-byte account once the IDL carries the
   * creator-fee fields.
   */
  async fetchGlobalConfigAccount(): Promise<GlobalConfig> {
    const accountInfo = await this.connection.getAccountInfo(GLOBAL_CONFIG_PDA);
    if (accountInfo === null) {
      throw new Error("Global config account not found");
    }
    return PUMP_AMM_SDK.decodeGlobalConfig(accountInfo);
  }

  createConfig(
    lpFeeBasisPoints: BN,
    protocolFeeBasisPoints: BN,
    protocolFeeRecipients: PublicKey[],
    coinCreatorFeeBasisPoints: BN,
    admin: PublicKey,
    adminSetCoinCreatorAuthority: PublicKey,
  ): Promise<TransactionInstruction> {
    return this.program.methods
      .createConfig(
        lpFeeBasisPoints,
        protocolFeeBasisPoints,
        protocolFeeRecipients,
        coinCreatorFeeBasisPoints,
        adminSetCoinCreatorAuthority,
      )
      .accountsPartial({
        admin,
      })
      .instruction();
  }

  disable(
    disableCreatePool: boolean,
    disableDeposit: boolean,
    disableWithdraw: boolean,
    disableBuy: boolean,
    disableSell: boolean,
    admin: PublicKey,
  ): Promise<TransactionInstruction> {
    return this.program.methods
      .disable(
        disableCreatePool,
        disableDeposit,
        disableWithdraw,
        disableBuy,
        disableSell,
      )
      .accountsPartial({
        admin,
        globalConfig: GLOBAL_CONFIG_PDA,
      })
      .instruction();
  }

  updateAdmin(
    admin: PublicKey,
    newAdmin: PublicKey,
  ): Promise<TransactionInstruction> {
    return this.program.methods
      .updateAdmin()
      .accountsPartial({
        admin,
        newAdmin,
        globalConfig: GLOBAL_CONFIG_PDA,
      })
      .instruction();
  }

  updateFeeConfig(
    lpFeeBasisPoints: BN,
    protocolFeeBasisPoints: BN,
    protocolFeeRecipients: PublicKey[],
    coinCreatorFeeBasisPoints: BN,
    admin: PublicKey,
    adminSetCoinCreatorAuthority: PublicKey,
  ): Promise<TransactionInstruction> {
    return this.program.methods
      .updateFeeConfig(
        lpFeeBasisPoints,
        protocolFeeBasisPoints,
        protocolFeeRecipients,
        coinCreatorFeeBasisPoints,
        adminSetCoinCreatorAuthority,
      )
      .accountsPartial({
        admin,
        globalConfig: GLOBAL_CONFIG_PDA,
      })
      .instruction();
  }

  /**
   * Overrides the coin creator of `mint`'s canonical pool. `quoteMint` is the coin's quote mint
   * (the bonding curve's zero key is accepted for SOL coins); it defaults to WSOL, the quote of
   * every coin created before quote mints existed.
   */
  async adminSetCoinCreator(
    mint: PublicKey,
    newCoinCreator: PublicKey,
    quoteMint: PublicKey = NATIVE_MINT,
  ): Promise<TransactionInstruction> {
    const globalConfig = await this.fetchGlobalConfigAccount();
    return this.program.methods
      .adminSetCoinCreator(newCoinCreator)
      .accountsPartial({
        pool: canonicalPumpPoolPda(mint, quoteMint),
        adminSetCoinCreatorAuthority: globalConfig.adminSetCoinCreatorAuthority,
        globalConfig: GLOBAL_CONFIG_PDA,
      })
      .instruction();
  }

  /**
   * Turns per-pool creator fees on or off and sets the ceiling `set_coin_creator_fee_bps`
   * accepts. Signed by `GlobalConfig.admin` (read from the account), who also pays the rent that
   * grows a pre-upgrade 940-byte GlobalConfig to `GLOBAL_CONFIG_SIZE` bytes, so it is the first
   * instruction to run after the program upgrade. While the gate is off, stored per-pool rates are
   * neither accepted by the setter nor read by trades.
   */
  async updateCreatorFeeConfig(
    creatorFeeConfigurable: boolean,
    maxConfigurableCreatorFeeBps: BN,
  ): Promise<TransactionInstruction> {
    const { admin } = await this.fetchGlobalConfigAccount();

    return this.program.methods
      .updateCreatorFeeConfig(
        creatorFeeConfigurable,
        maxConfigurableCreatorFeeBps,
      )
      .accountsPartial({
        admin,
        globalConfig: GLOBAL_CONFIG_PDA,
      })
      .instruction();
  }

  async adminUpdateTokenIncentives(
    startTime: BN,
    endTime: BN,
    dayNumber: BN,
    tokenSupplyPerDay: BN,
    secondsInADay: BN = new BN(86400),
    mint: PublicKey = PUMP_MINT,
    tokenProgram: PublicKey = TOKEN_2022_PROGRAM_ID,
  ): Promise<TransactionInstruction> {
    const { admin } = await this.fetchGlobalConfigAccount();

    return this.program.methods
      .adminUpdateTokenIncentives(
        startTime,
        endTime,
        secondsInADay,
        dayNumber,
        tokenSupplyPerDay,
      )
      .accountsPartial({
        admin,
        mint,
        tokenProgram,
      })
      .instruction();
  }
}
